  "一般組分 3 個招生群類 + 青年儲蓄帳戶組 2 名；設計群 205036（21+1 名）是動遊系最大入學管道。": "一般枠は3つの募集専門群に分かれ、さらに青年貯蓄口座枠が2名あります。デザイン群 205036（21+1名）はアニメとゲームデザイン学科最大の入試制度です。",
  "四技日間部甄選入學 — 透過聯合招生，採統測 + 校系自辦指定項目甄試的入學管道。 115學年度一般組：高職等專業群科畢業生不限應屆；普通科畢業滿1年，或符合簡章同等學力等資格者也可申請。綜高應屆須截至高三上修畢專門學程25學分。普通科應屆原則不適用；若截至高三上跨選專業群科或專門學程達25學分或450小時，依簡章另核。須取得115統測成績，且符合群類、校系及其他資格限制；青年儲蓄帳戶組另核。 樹德動遊系一次開出 4 個招生代碼（一般組 3 群 + 青年儲蓄帳戶組），115學年度甄選入學最多可申請6個校系科（組）、學程，各校得另限制可報名該校的系科數；請依當年簡章核對。 錄取流程： 1. 統測成績進入第一階段篩選 2. 通過篩選者上傳第二階段備審資料 3. 第二階段甄試到校 — 書審 + 面試 + 實作（設計群） 4. 公告總成績 + 正備取名單 5. 登記就讀志願序 → 統一分發 → 報到 須備：學習歷程檔案、作品集（設計群）、自傳、讀書計畫": "4年制課程昼間部 甄選入学（選抜入試） — 合同募集を通じ、統測成績＋大学学科独自の指定選考を実施する入試制度。115学年度一般枠：専門群科の卒業者・条件を満たす卒業見込者、普通科卒業後1年以上の者、募集要項の同等学力等の条件を満たす者が対象です。総合高校の卒業見込者は、高校最終学年の前期末までに専門課程（專門學程）25単位の修得が必要です。普通科の卒業見込者は原則対象外ですが、その時点までに専門群科または専門課程の科目を跨選（他課程の科目履修）して25単位または450時間に達する場合は、募集要項に基づく個別確認が必要です。115学年度の統測成績に加え、受験区分、志望学科等の条件とその他の出願資格制限も満たす必要があります。青年貯蓄口座枠は別途確認してください。 樹徳科技大学アニメとゲームデザイン学科では4つの募集コード（一般枠3群＋青年貯蓄口座枠）を開設しており、115学年度は、大学・学科（専攻・学位課程）の選択を合計6件まで申請できます。各大学が自校の出願先数を別途制限する場合もあるため、当該年度の募集要項で確認してください。選考プロセス：1. 統測成績による第1段階スクリーニング 2. 通過者による第2段階審査書類のアップロード 3. 第2段階の来校選考 — 書類選考＋面接＋実技試験（デザイン群） 4. 総合点発表＋合格・補欠合格者リスト公表 5. 進学志望順位登録 → 統一割当 → 入学手続き 提出書類：学習履歴ファイル、ポートフォリオ（デザイン群）、自伝（自己紹介・経歴をまとめた書類）、学習計画書",
