  "限應屆高職 / 綜合高中畢業生，校內遴選推薦制。": "専門高校／総合高校の卒業見込者限定、校内選考による学校推薦制。",
  "科技校院繁星計畫 — 由就讀學校依在校成績推薦，不採計統測的學校推薦制管道。 適用對象：應屆高職 / 綜合高中畢業生 申請資格： ● 限國內公立或已立案私立高級中等學校（高職、綜合高中）的應屆畢業生 ● 全程就讀國內同一學校 ● 在校學業成績總平均排名百分比須符合招生簡章規定的標準 申請流程重點： ● 學校推薦制 — 學生無法以個人名義報名，請洽就讀學校註冊組或輔導室 ● 已報名「大學繁星推薦」（高中管道）者，不得重複報名「科技繁星」 ● 主要依在校學業成績總平均排名百分比進行比序": "科学技術大学スター選抜（科技校院繁星計画） — 在籍校での学業成績に基づき推薦され、統測成績を利用しない学校推薦型選抜制度。適用対象：専門高校／総合高校の卒業見込者 出願資格：● 台湾国内の公立または認可私立高級中等学校（専門高校、総合高校）の卒業見込者に限定 ● 全期間を国内の同一校に在籍 ● 高校での学業総合成績の順位パーセンタイルが募集要項の基準を満たしていること 出願プロセスの要点：● 学校推薦制 — 生徒個人での出願は不可、在籍校の教務・登録担当または進路指導室にお問い合わせください ● 「大学繁星推薦」（普通科高校枠）に出願した者は、「科技繁星」に重複出願できません ● 主に校内学業総合成績の順位パーセンタイルに基づき順位を判定",
  "🏫 校內遴選由就讀高職 / 綜合高中辦理 — 請洽就讀學校註冊組或輔導室": "🏫 校内選考は在籍する専門高校／総合高校が実施 — 在籍校の教務担当または進路指導室にお問い合わせください",
  "📊 在校成績總平均排名百分比是核心比序項目": "📊 校内総合成績の順位パーセンタイルが最重要の判定基準",
  "🚫 115 學年度科技繁星錄取生，不論是否放棄，均不得參加當年度四技二專甄選入學；其他管道請依各招生簡章與報到／放棄規定辦理。": "🚫 115学年度の科技繁星合格者は、入学資格を辞退したかどうかにかかわらず、当該年度の四技二専甄選入学（選抜入試）には出願できません。その他の入試区分は、それぞれの募集要項、入学手続き・辞退の規定に従ってください。",
  "🎯 最早確定錄取的管道之一（5/5 分發）": "🎯 最も早く進学先が確定する入試制度の一つ（5/5 割当発表）",
  "🏫 校內遴選由就讀高職 / 綜合高中辦理 — 請洽就讀學校": "🏫 校内選考は在籍する専門高校／総合高校が実施 — 在籍校にお問い合わせください",
  "📊 比序：在校成績總平均 → 同分時看群修科目成績、英文、國文、相關證照": "📊 順位判定：校内総合成績 → 同点時は群履修科目成績、英語、国語、関連する資格・検定の順",
  "🎯 樹德動遊系設計群 3 名 — 各群熱門校系競爭，建議提早跟學校老師討論": "🎯 樹徳科技大学アニメとゲームデザイン学科デザイン群 3名 — 各群の人気学科として競争率が高いため、早めに在籍校の教員と相談することをおすすめします",
  "✅ 入學後即享受與其他管道完全相同的師資、實驗室、產學資源": "✅ 入学後は他の入試制度と全く同様の教員陣、実習室・ラボ、産学連携リソースを活用可能",
