  "競賽優勝、採認證照等資格甄審（115學年度85商設類別；依當年簡章）。": "競技大会の入賞や対象資格に基づく選考（115学年度・85商業デザイン類。詳細は当該年度の募集要項）。",
  "技優甄審入學 — 依115學年度簡章審查技藝技能競賽優勝、採認證照等資格的入學管道。 適用對象：符合當年簡章學歷與資格規定者，不只限應屆畢業生。可採認的資格包括競賽優勝、勞動部乙級（含）以上技術士證等；證照職（種）類與招生類別須符合簡章，並非持任一乙級證照即可報名本系。 錄取流程： 1. 第一階段：報名 + 繳費 + 上傳當年簡章要求的資格證明 / 作品集 2. 第二階段：書面審查（樹德動遊系不含現場實作） 3. 公告甄審結果 → 登記志願序 → 統一分發 → 報到": "技優甄審入試 — 115学年度の募集要項に基づき、技能競技大会の入賞や対象資格などを審査する入試制度。対象者：当該年度の学歴・資格要件を満たす方。卒業見込者だけに限りません。対象となる資格には、所定の競技大会での入賞、台湾の労働部発行の乙級以上の「技術士證」（台湾の技能検定資格）などがあります。資格の職種と募集区分は要項に適合する必要があり、任意の乙級資格を持っていれば本学科へ出願できるわけではありません。 選考プロセス： 1. 第1段階：出願 + 納付 + 当該年度の要項が求める資格証明書／ポートフォリオの提出 2. 第2段階：書類審査（樹徳科技大学アニメとゲームデザイン学科は実技試験なし） 3. 選考結果発表 → 志望順位登録 → 一括配分 → 入学手続き",
  "📜 依115簡章審查競賽優勝、勞動部乙級（含）以上技術士證等資格；須符合招生職種與類別。": "📜 115学年度の要項に基づき、所定の競技大会入賞、台湾の労働部発行の乙級以上「技術士證」（台湾の技能検定資格）などを審査。職種・募集区分の適合が必要です。",
  "🎯 16 名名額 — 是樹德動遊系第二大入學管道": "🎯 定員 16 名 — 樹徳科技大学アニメとゲームデザイン学科で2番目に大きい入試枠",
