  "📅 與其他四技管道時程不衝突，建議搭配甄選入學雙軌進行": "📅 他の4年制課程入試と日程が重複しないため、甄選入学（選抜入試）との併願を推奨",
  "🏆 樹德動遊系收 85 商設群 — 設計學院最大組": "🏆 樹徳科技大学アニメとゲームデザイン学科は 85 商業デザイン群を募集 — デザイン学部最大のグループ",
  "📜 競賽與證照須符合115簡章採認職（種）類及85商設招生類別，請先查資格對照表。": "📜 大会・資格の職種は115学年度の対象職種と85商業デザイン類に適合する必要があります。先に資格対照表を確認してください。",
  "🎤 樹德第二階段：書面審查（不含現場實作）": "🎤 樹徳科技大学の第2段階：書類審査（実技試験なし）",
