  "統測 4/25-4/26｜登記 7/28-7/31｜放榜 8/06": "統測 4/25-4/26｜登録 7/28-7/31｜合格発表 8/06",
  "純看統測加權分數分發，無須校系甄試。": "統測の加重配点スコアのみで配分選抜され、大学・学科の個別試験は不要。",
  "四技日間部聯合登記分發 — 純採統測加權分數分發，不需面試 / 書審 / 作品集的入學管道。 適用對象：參加四技二專統一入學測驗（統測）的考生 樹德動遊系一次開 3 個招生代碼。學生填寫志願序，由系統依統測分數高低統一分發 — 是進入動遊系的「最後機會」。": "4年制課程昼間部 聯合登記分発 — 統測の加重配点スコアのみで配分選抜され、面接／書類審査／ポートフォリオが不要な入試制度。 適用対象：4年制大学・2年制専科学校統一入学テスト（統測）を受験した生徒 樹徳科技大学アニメとゲームデザイン学科では3つの募集コードを設置。学生が志望順位を登録後、システムが統測の得点順に一括配分 — アニメとゲームデザイン学科に入るための「最後のチャンス」です。",
