  "💰 達標可同步爭取設計學院菁英獎學金（10-43 萬）": "💰 基準を満たすとデザイン学部エリート奨学金（10-43 万）の対象に",
  "🎯 設計群 07064（3 名 + 原住民 1 名）為動遊系主力": "🎯 デザイン群 07064（3 名 + 原住民族 1 名）がアニメとゲームデザイン学科の主力",
  "⏱ 是進入動遊系的「最後機會」— 8/06 放榜後即開學": "⏱ アニメとゲームデザイン学科に入る「最後のチャンス」— 8/06 合格発表後まもなく新学期が始まります",
