  "💰 達標可同步爭取設計學院菁英獎學金（10-43 萬）— 第一志願填樹德動遊系即自動入列": "💰 基準を満たすとデザイン学部エリート奨学金（10-43 万）の対象に — 第1志望に樹徳科技大学アニメとゲームデザイン学科を登録すれば自動的に選考対象となります",
  "📊 設計群加權：(專 1 + 專 2) × 3 + 國 × 2 + 英 + 數，達 420 入列獎學金": "📊 デザイン群加重：(専 1 + 専 2) × 3 + 国 × 2 + 英 + 数、420 到達で奨学金対象",
