  "請見樹德進修部專區": "樹徳科技大学進修部特設ページをご確認ください",
  "獨立招生｜採書審 + 面試": "独自募集｜書類審査 + 面接",
  "包含二技 / 四技 / 二專進修部與產學攜手。目前頁面未列出動遊系名額 — 請洽樹德進修部專區。": "2年制大学／4年制課程／2年制短期大学の進修部および産学連携プログラムを含みます。現在ページ上にアニメとゲームデザイン学科の定員は記載されていません — 樹徳科技大学進修部特設ページへお問い合わせください。",
  "進修部相關招生 — 涵蓋二技 / 四技 / 二專進修部與產學攜手計畫，採書審 + 面試（免統測 / 學測）的彈性入學管道。 適用對象：在職人士、想兼顧工作與學業者、二度就讀者 上課時間：典型週一至五晚上 18:30-21:30 + 部分假日課程。 ※ 各管道是否開放動遊系名額，請以樹德招生網對應專區公告為準。": "進修部関連募集 — 2年制大学／4年制課程／2年制短期大学の進修部および産学連携プログラムを網羅し、書類審査 + 面接（統測／学測不要）で実施される柔軟な入試制度です。 適用対象：社会人、仕事と学業を両立したい方、学び直し希望者 授業時間：通常は月曜日〜金曜日夜間 18:30-21:30 + 一部休日の授業。 ※ 各入試枠におけるアニメとゲームデザイン学科の定員の有無は、樹徳科技大学受験生向けサイトの各募集特設ページのご案内をご確認ください。",
  "📌 目前頁面未列出動遊系名額 — 請定期關注樹德招生網": "📌 現在ページ上にアニメとゲームデザイン学科の定員は掲載されていません — 樹徳科技大学受験生向けサイトを定期的にご確認ください",
  "📞 動遊系系辦：6102（07-6158000）可諮詢進修部開放狀況": "📞 アニメとゲームデザイン学科事務室：6102（07-6158000）進修部の募集状況についてお問い合わせいただけます",
  "🌙 進修部上課多為週一至五 18:30-21:30": "🌙 進修部の授業は主に月曜日〜金曜日 18:30-21:30",
  "🎓 進修部畢業證書與日四技完全相同": "🎓 進修部の卒業証書は昼間部4年制課程と完全に同一です",
  "🌙 上課時間：週一至五 18:30-21:30 + 部分假日課程": "🌙 授業時間：月曜日〜金曜日 18:30-21:30 + 一部休日の授業",
