  "依設計群／商管群統測加權後總分自動入列；聯分第一志願填樹德動遊系即啟動。": "設計群／商管群の統測加重後総合点に基づき自動選考；聯分の第1志望に樹徳科技大学アニメとゲームデザイン学科を登録することで適用されます。",
  "樹德設計學院菁英、群英招募獎助學金 — 不是入學管道，是入學後的高額獎助方案。 申請資格： ● 當年度參加四技二專統一入學測驗，成績達設置標準（加權後總分） ● 聯合登記分發第一志願選填樹德科技大學設計學院指定科系 設計群門檻：國文 + 英文 + 數學 +（專 1 + 專 2）×2 達 420 分以上 商管群門檻：國文 + 英文 + 數學 +（專 1 + 專 2）×2 達 400 分以上 不需另行申請 — 統測達標 + 聯分第一志願填本系即自動入列。入學後依在校成績維持資格分學期／學年核發；部分高額方案需於就學期間維持指定學業成績與專業表現。": "樹徳科技大学デザイン学部エリート・群英スカウト奨学金 — 入試制度ではなく、入学後に支給される高額奨学金制度です。 申請資格： ● 当該年度に4年制大学・2年制専科学校統一入学テストを受験し、成績が規定基準（加重後総合点）を満たしていること ● 聯合登記分発で第1志望として樹徳科技大学デザイン学部の指定学科を選択していること 設計群基準：国語 + 英語 + 数学 +（専門 1 + 専門 2）×2 が 420 点以上 商管群基準：国語 + 英語 + 数学 +（専門 1 + 専門 2）×2 が 400 点以上 個別申請は不要 — 統測で基準を達成し、聯分の第1志望に本学科を選択すれば自動的に選考対象となります。入学後は学業成績の継続条件に基づき学期／学年ごとに支給されます；一部の高額プランは在学中に指定の学業成績および専門実績を維持する必要があります。",
  "💎 高額方案（30-43 萬）需在學期間維持指定學業成績 + 專業表現": "💎 高額プラン（30-43 万）は在学中に指定の学業成績 + 専門実績の維持が必要",
  "🎓 部分方案可直接抵免學雜費 — 4 年學費全免有可能": "🎓 一部プランは授業料・諸費用と直接相殺可能 — 4 年間の学費全額免除も可能",
  "📋 達標自動入列 — 不需另寫申請、不需面試、不需作品集": "📋 基準達成で自動選考 — 個別の申請書類作成、面接、ポートフォリオすべて不要",
