  "一、開課名稱：「ACP Photoshop」國際證照輔導班 二、上課日期：115/12/12(六)、115/12/13(日) 三、證照考試：115/12/13(日) 四、上課地點：D0235 教室 五、招生名額：15 人，額滿為止，可依序排列候補；報名學生需配合全程參與，不得缺課，並同意參加證照考試。 六、報名時間：即日起，至額滿為止。 報名方式：請洽負責老師或系辦（分機 6102）。 主辦單位：動畫與遊戲設計系 協辦單位：研究發展處職涯發展暨校友服務中心 負責老師：江雅媚老師，分機 6109，Email: cym68@stu.edu.tw": "一、講座名：「ACP Photoshop」国際資格・検定対策講座 二、講義日程：115/12/12(土)、115/12/13(日) 三、資格・検定試験：115/12/13(日) 四、実施場所：D0235教室 五、募集定員：15名、定員に達し次第締切（順次キャンセル待ち受付）。申込学生は全日程の出席（欠席不可）および資格・検定試験の受験に同意する必要があります。 六、申込期間：告知日から受付を開始し、定員に達し次第締切。 申込方法：担当教員または学科事務室（内線 6102）までお問い合わせください。 主催：アニメとゲームデザイン学科 共催：研究発展処キャリア発展・卒業生サービスセンター 担当教員：江雅媚教員、内線 6109、Email: cym68@stu.edu.tw",
  "國際": "国際",
  "《癡迷的現實》再添 5 項國際影展 · 累計 13 項橫跨 7 國": "《癡迷的現實》がさらに5つの国際映画祭に選出 · 累計13件・世界7カ国に広がる",
  "杜拜、芝加哥、希瓦吉、東京、義大利旅遊影展同月報到 — 陳美蓉老師指導的動畫短片《癡迷的現實》國際入圍提名累計達 13 項。": "ドバイ、シカゴ、シヴァージー、東京、イタリア観光映画祭に同じ月にノミネート・選出——陳美蓉教員が指導する短編アニメーション《癡迷的現實》が、国際映画祭でのノミネート・入選累計13件を達成しました。",
  "【高雄訊】樹德科技大學動畫與遊戲設計系（動遊系）學生原創動畫《癡迷的現實》再傳捷報。繼今年 4 月以 8 項國際影展紀錄登上系上「四部學生動畫橫掃國際影展」專題後，該片近日再獲阿拉伯聯合大公國、美國、印度、日本、義大利等五國影展青睞，一口氣新增 5 項入圍與提名，國際影展入圍提名累計達 13 項，足跡橫跨 7 個國家。 ■ 本次新增 5 項 • 阿拉伯聯合大公國「杜拜獨立影展」Dubai Independent Film Festival — Best Student Short 競賽單元 · 半決賽入圍 • 美國「芝加哥獨立影展」Chicago Indie Film Awards — Best Student Film 競賽單元 · 提名 • 印度「希瓦吉國際影展」Chhatrapati Shivaji International Film Festival — Animated Short Film 競賽單元 · 入圍 • 日本「東京國際電影獎」Tokyo International Cinema Awards — Best Animation 競賽單元 · 提名 • 第 15 屆「義大利國際旅遊影展」International Tour Film Festival — Animation 競賽單元 · 入圍 ■ 關於作品 《癡迷的現實》由動遊系學生陳志揚、宋秋陽、藤川黎星共同創作，陳美蓉老師指導。全片採 2D 數位手繪製作，以 1980 年代懷舊美術風格鋪陳偶像崇拜與理性認知之間的衝突，探討「單純喜歡」與「完全迷戀」之間的界線，提醒觀眾癡迷往往源自於了解不足，唯有理性支持才是真正的成長。作品呼應 SDG 4「優質教育」與 SDG 12「負責任消費與生產」，在社群時代的媒體素養議題上展現高度思辨性。 ■ 國內戰績 第 21 屆技專校院電腦動畫競賽「佳作」、2025 巴哈姆特 ACG 創作大賽動畫組「優選賞」、第 17 屆小花豹青年短片大獎「最佳劇情短片」，並入圍 2025 放視大賞 2D 動畫組。 指導老師陳美蓉表示，一部學生畢業製作能持續在不同國家的影展被看見，代表作品談的議題本身跨越了語言與文化。系主任鄧樹遠指出，動遊系長期強調「實務創作 × 社會價值」，鼓勵學生把畢業製作視為進入國際市場的第一張作品集，而非課程的終點。": "【高雄発】樹徳科技大学アニメとゲームデザイン学科の学生によるオリジナルアニメーション《癡迷的現實》が再び快挙を達成しました。今年4月に8つの国際映画祭選出実績によって学科の特集「四部學生動畫橫掃國際影展」に掲載されたのに続き、同作は先ごろ新たにアラブ首長国連邦、アメリカ、インド、日本、イタリアの5カ国の映画祭でも高く評価され、一挙に5つのノミネートおよび入選を果たしました。これにより国際映画祭でのノミネート・入選は累計13件に達し、世界7カ国に足跡を刻んでいます。 ■ 今回新たに追加された5件 • アラブ首長国連邦「ドバイ独立映画祭」Dubai Independent Film Festival — Best Student Short コンペティション部門 · セミファイナリスト • アメリカ「シカゴ・インディペンデント映画賞」Chicago Indie Film Awards — Best Student Film コンペティション部門 · ノミネート • インド「チャトラパティ・シヴァージー国際映画祭」Chhatrapati Shivaji International Film Festival — Animated Short Film コンペティション部門 · 入選 • 日本「東京国際映画賞」Tokyo International Cinema Awards — Best Animation コンペティション部門 · ノミネート • 第15回「イタリア国際ツアー映画祭」International Tour Film Festival — Animation コンペティション部門 · 入選 ■ 作品について 《癡迷的現實》は、アニメとゲームデザイン学科の学生である陳志揚、宋秋陽、藤川黎星が共同制作し、陳美蓉教員が指導を担当しました。全編2Dデジタル手描きで制作され、1980年代のレトロな美術スタイルを通じてアイドル崇拝と理性的認知の葛藤を描写。「純粋な好意」と「完全な執着」の境界を探求し、盲信や執着は往々にして理解不足から生じるものであり、理性的な応援こそが真の成長につながることを観客に問いかけています。本作品はSDG 4「質の高い教育をみんなに」およびSDG 12「つくる責任 つかう責任」に呼応し、ソーシャルメディア時代におけるメディアリテラシーの課題に対して深い思弁性を発揮しています。 ■ 台湾国内での実績 第21回技專校院電腦動畫競賽「佳作」、2025巴哈姆特ACG創作大賽アニメーショングループ「優選賞」、第17回小花豹青年短片大獎「最佳劇情短片」を受賞し、2025放視大賞2Dアニメーショングループに入選。 指導教員の陳美蓉は、「学生の卒業制作が各国の映画祭で継続的に評価されていることは、作品が扱うテーマ自体が言語や文化を超越している証です」と述べました。学科長の鄧樹遠は、「アニメとゲームデザイン学科では長期にわたり『実践的創作 × 社会的価値』を重視しており、卒業制作を単なる履修の終着点ではなく、国際市場へ進出するための最初のポートフォリオとして位置づけるよう学生を奨励しています」と指摘しました。",
