  "以 1980 年代懷舊美術風格呈現偶像崇拜與理性認知的衝突，融入 SDG 4「優質教育」與 SDG 12「負責任消費與生產」。國際影展入圍提名累計 13 項，橫跨西、土、美、印、阿聯、日、義 7 國。": "1980年代のレトロな美術スタイルでアイドル崇拝と理性的認知の葛藤を描き、SDG 4「質の高い教育をみんなに」およびSDG 12「つくる責任 つかう責任」を取り入れました。国際映画祭でのノミネート・入選は累計13件に達し、スペイン、トルコ、アメリカ、インド、アラブ首長国連邦、日本、イタリアの世界7カ国にまたがっています。",
