  "簡敬儒 · 林維仁 · 葉賜宏 · 李嘉楡 · 何政哲": "簡敬儒 · 林維仁 · 葉賜宏 · 李嘉楡 · 何政哲",
  "以音樂節奏為核心的第三人稱戰鬥冒險遊戲。創新整合 MIDI 鍵盤作為實體鋼琴互動介面，將演奏力道與觸鍵手感直接轉化為遊戲內的視聽回饋與戰鬥動能。玩家化身穿梭奇幻大地的「環境音樂治療師」，融合凱爾特神話世界觀與美式圖像小說質感的非寫實渲染。": "音楽リズムを中核とする三人称視点バトルアドベンチャーゲーム。MIDIキーボードを実体的なピアノ操作インターフェースとして革新的に統合し、演奏の強弱や打鍵感をゲーム内の視聴覚フィードバックや戦闘アクションの推進力へとダイレクトに変換します。プレイヤーは幻想的な世界を巡る「環境音楽セラピスト」となり、ケルト神話の世界観とアメリカン・グラフィックノベル調の質感を融合させたノンフォトリアリスティック・レンダリングで描かれます。",
