  "神癒": "神癒",
  "陳彥蓉 · 陳珮羚 · 陳儀臻 · 方娸伊": "陳彥蓉 · 陳珮羚 · 陳儀臻 · 方娸伊",
  "結合科技與信仰的奇幻短片，於西班牙巴塞隆納「愛情影展」第 8 屆勇奪『最佳奇幻類 Best Fantastic』獎項，並入圍 2025 巴塞隆納作者電影節、印度孟買國際影片獎、放視大賞 2D 動畫組。": "テクノロジーと信仰を融合させたファンタジー短編映画。スペイン・バルセロナ「Love Film Festival」第8回にて『最優秀ファンタジー部門 Best Fantastic』を受賞し、2025年バルセロナ作者映画祭、インド・ムンバイ国際映画賞、放視大賞2Dアニメーション部門に入選しました。",
  "Love Film Festival 第 8 屆 · 最佳奇幻類 ★": "Love Film Festival 第8回 · 最優秀ファンタジー部門 ★",
