  "109-112 學年度 · 平均就業比 94%": "109〜112学年度 · 平均就業比率 94%",
  "109-112 學年度日四技 + 夜四技畢業生流向統計，就業比平均 94%，其中夜四技 110 / 111 學年度達 100%。資料來源：教育部委託國立臺灣師範大學「畢業生離校前、畢業一年後流向追蹤調查平台系統」。": "109〜112学年度の4年制課程（昼間部）＋4年制課程（夜間部）卒業生進路統計では、就業比率が平均94％に達し、そのうち4年制課程（夜間部）は110／111学年度に100％を達成しました。出所：教育部委託 国立台湾師範大学「卒業生離校前・卒業1年後進路追跡調査プラットフォームシステム」。",
