  "就業比 = (就業 + 服兵役 + 留學 + 接案) ÷ 有效追蹤人數。實際追蹤時聯絡不上者佔比不低，校方持續強化校友會 / 導師聯繫機制。": "就業比率＝（就業＋兵役＋留学＋受託案件）÷ 有効追跡人数。実際の追跡調査において連絡がつかない者の割合も低くないため、大学は同窓会／指導教員（メンター）との連絡体制の強化を継続しています。",
