  "邀請業界專業師資進入課堂，學生直接學業界實戰技能。包括跨域講座、橫山盃高中職競賽、虛擬角色工作坊、設計國際研討會、台灣數位媒體設計競賽，以及每年「設計師工作室」課程連續邀請業界 SOHO 設計師授課。": "業界の専門講師を授業に招き、学生が直接業界の実践的なスキルを学びます。領域横断講座、横山杯高校生コンテスト、バーチャルキャラクターワークショップ、デザイン国際シンポジウム、台湾デジタルメディアデザインコンテスト、そして毎年「デザイナーズスタジオ」科目において継続的に業界のSOHOデザイナーを招いて授業を実施しています。",
