  "業師組成涵蓋影像、動畫、品牌、工作室創業、虛擬角色等領域；張純雅老師主持的「設計師工作室」課程已成為跨年度業師輪訓的核心場域。": "業界プロ講師の構成は映像、アニメ、ブランディング、スタジオ起業、バーチャルキャラクターなどの領域を網羅。張純雅教員が担当する「デザイナーズスタジオ」科目は、複数年度にわたる業界プロ講師連携指導の中核的な場となっています。",
  "教師教材編纂 × 教具製作 × 專利": "教員による教材編纂 × 教具制作 × 特許",
