  "5 個學年內動遊系教師累積完成 80+ 件教學編纂與教具製作，並由江雅媚老師主導取得 6 件國家專利（新型 / 發明 / 設計）。教材涵蓋 2D 動畫、3D 建模、遊戲程式、互動設計、品牌、行銷、企劃等全方位課程。": "5学年間でアニメとゲームデザイン学科の教員は累計80件以上の教材編纂および教具制作を達成し、江雅媚教員の主導により6件の国家特許（実用新案／発明／意匠）を取得しました。教材は2Dアニメ、3Dモデリング、ゲームプログラミング、インタラクティブデザイン、ブランディング、マーケティング、企画など全方位のカリキュラムを網羅しています。",
