  "與日本（含沖繩）、韓國、印尼 3 國共 8 家公司合作。每年透過教育部「學海築夢」計畫派遣優秀學生赴 Hautecouture 株式會社（日本愛媛縣松山市）實習，2023 年復辦後累計 22 位學生赴日完成業界專案。": "日本（沖縄含む）、韓国、インドネシアの3カ国計8社と連携。毎年、教育部「学海築夢」計画を通じて優秀な学生をHautecouture株式会社（愛媛県松山市）へインターンシップに派遣し、2023年の再開以降、累計22名の学生が訪日して業界プロジェクトを完遂しました。",
