  "動遊系畢業門檻含「專業證照」要求，109-113 學年度學生累積取得 811 張證照，涵蓋 Adobe / Autodesk / Unity 國際原廠認證、TQC+ 視傳設計、ITE 資訊專業人員、iPAS 經濟部產業人才能力鑑定等四大體系。系上每年開辦 4 場左右證照輔導班，由本系教師親自指導。": "アニメとゲームデザイン学科の卒業要件には「専門資格・検定」が含まれており、109-113学年度にかけて学生は累計811件の資格・検定を取得しました。これらはAdobe / Autodesk / Unityの国際ベンダー公式認定、TQC+視覚伝達デザイン、ITE情報専門人材、経済部iPAS産業人材能力検定の4大体系を網羅しています。学科では毎年4回程度の資格・検定対策講座を開講し、本学科の教員が直接指導を行っています。",
