  "2025 全國技專校院實務專題製作競賽 — 動漫互動多媒體類別 入圍（從 1,181 件作品中脫穎而出）": "2025 全國技專校院実践プロジェクト制作コンテスト — アニメ・インタラクティブマルチメディア部門 ノミネート（応募1,181作品の中から選出）",
  "第 21 屆技專校院電腦動畫競賽 — 直接參賽組 佳作": "第21回 技專校院電腦動畫競賽 — 直接エントリー部門 佳作",
  "由涂承恩、李冠霖、張淑盈、唐莉蓉共同創作，陳美蓉老師指導的 2D 動畫短片《失竊的祕方》。 故事以「誤解與和解」為主題，描繪一位老廚師因祕方書失竊而誤會新餐廳老闆。透過角色造型與視覺敘事對比，引發觀眾對「以貌取人」的反思，並融合 SDGs 性別平等、減少不平等及和平正義等核心理念。": "陳美蓉教員の指導のもと、涂承恩、李冠霖、張淑盈、唐莉蓉が共同制作した2Dアニメーション短編《失竊的祕方》。本作は「誤解と和解」をテーマに、秘伝のレシピ本が盗まれたことで新しいレストランのオーナーを誤解してしまう老料理人の物語を描いています。キャラクターの造形と視覚的ナラティブの対比を通じて、観客に「外見で人を判断すること」への省察を促し、SDGsのジェンダー平等、不平等の是正、平和と公正などのコア理念を融合させています。",
  "《癒光之音：悅曲》": "《癒光之音：悅曲》",
  "教育部入圍": "教育部 入選",
  "教育部 2026 年全國技專校院學生實務專題製作競賽暨成果展 入圍": "教育部 2026年 全國技專校院學生實務專題製作競賽暨成果展 入選",
  "「於此，奏響名為希望的樂曲」（Soothing Sounds: The Enchanting Music）。融合奇幻角色設計、細膩光影演出與東方神祕意象的遊戲作品。 入圍教育部 2026 年全國技專校院學生實務專題製作競賽暨成果展。": "「ここに、希望という名の楽曲を奏でる」（Soothing Sounds: The Enchanting Music）。ファンタジー調のキャラクターデザイン、繊細な光影の演出、東洋の神秘的なイメージを融合させたゲーム作品です。教育部 2026年 全國技專校院學生實務專題製作競賽暨成果展に入選しました。",
  "巴哈姆特 ACG 創作大賽 · 優選雙獎": "巴哈姆特 ACG 創作大賽 · 優選賞ダブル受賞",
  "優選 × 2": "優選賞 × 2",
  "原創動畫": "オリジナルアニメーション",
  "《人造人》博浩原、戎軒頤、陳政名、李育賢；《癡迷的現實》宋秋陽、陳志揚、藤川黎星": "《人造人》博浩原、戎軒頤、陳政名、李育賢；《癡迷的現實》宋秋陽、陳志揚、藤川黎星",
  "巴哈姆特 ACG 創作大賽 · 優選賞 ×2（從全台 69 件入圍作品中脫穎而出）": "巴哈姆特 ACG 創作大賽 · 優選賞 ×2（台湾全土69件のノミネート作品の中から選出）",
  "《人造人》— 呼應 SDG 16「和平、正義及健全制度」": "《人造人》— SDG 16「平和と公正をすべての人に」に呼応",
  "《癡迷的現實》— 1980 懷舊風 · 融入 SDG 4 與 SDG 12": "《癡迷的現實》— 1980年代ノスタルジック風 · SDG 4 と SDG 12 を融合",
  "2025 年度「ACG 創作大賽」由台灣最大 ACG 社群平台──巴哈姆特電玩資訊站舉辦。動遊系兩部原創動畫《人造人》與《癡迷的現實》同時榮獲「優選賞」，在全台 69 件入圍作品中脫穎而出。 《人造人》以人造智慧生命為主題，呼應 SDG 16「和平、正義及健全制度」。 《癡迷的現實》以 1980 年代懷舊美術風格呈現偶像崇拜與理性認知的衝突，融入 SDG 4「優質教育」與 SDG 12「負責任消費與生產」。": "2025年度「ACG 創作大賽」は、台湾最大のACGコミュニティプラットフォーム「巴哈姆特電玩資訊站」が主催。アニメとゲームデザイン学科のオリジナルアニメーション2作品《人造人》と《癡迷的現實》が同時に「優選賞」を受賞し、台湾全土69件のノミネート作品の中から見事選出されました。《人造人》は人工的に生み出された知的生命をテーマとし、SDG 16「平和と公正をすべての人に」に呼応しています。《癡迷的現實》は1980年代のノスタルジックな美術スタイルでアイドル崇拝と理性的認知の衝突を描き、SDG 4「質の高い教育をみんなに」およびSDG 12「つくる責任 つかう責任」を取り入れています。",
  "時報金犢獎國際競賽 · 第二名": "時報金犢獎国際コンテスト · 第2位",
  "第二名 + 18 組入圍": "第2位 + 18組ノミネート",
  "廣告動畫": "広告アニメーション",
  "裴欣慧、黃若庭、王巧安、蔡思淇": "裴欣慧、黃若庭、王巧安、蔡思淇",
  "第 34 屆時報金犢獎國際競賽 · 永慶房屋招募廣告類 第二名": "第34回 時報金犢獎国際コンテスト · 永慶房屋招募廣告部門 第2位",
  "從全球上萬件參賽作品中脫穎而出": "世界中の1万件を超える応募作品の中から選出",
  "本系整體入圍 18 組（張純雅 11 組 + 陳美蓉 7 組）": "学科全体で計18組がノミネート（張純雅 指導11組 + 陳美蓉 指導7組）",
  "第 34 屆時報金犢獎國際競賽 — 永慶房屋雇主品牌招募廣告系列篇（柴犬篇、浣熊篇、松鼠篇）榮獲「永慶房屋招募廣告類」第二名，從全球上萬件參賽作品中脫穎而出。 運用動物角色設定，將「不綁約」、「不爆肝」、「不扣薪」三大招募訴求轉化為輕鬆幽默的視覺語言。": "第34回 時報金犢獎国際コンテストにおいて、『永慶房屋雇主品牌招募廣告系列篇（柴犬篇、浣熊篇、松鼠篇）』が「永慶房屋招募廣告類」第2位を受賞し、世界中から集まった1万件以上の応募作品の中から選出されました。動物キャラクターの設定を活用し、「契約縛りなし（不綁約）」、「過度な残業なし（不爆肝）」、「給与カットなし（不扣薪）」の3大採用アピールを、軽快でユーモアあふれる視覚言語へと昇華させました。",
  "2025 放視大賞 · 8 件入圍": "2025 放視大賞 · 8作品ノミネート",
