  "8 個畢業專題團隊": "8つの卒業制作チーム",
  "陳美蓉、邱士展、陳慶鴻、鄧樹遠、蔣天華": "陳美蓉、邱士展、陳慶鴻、鄧樹遠、蔣天華",
  "動畫類 5 件入圍": "アニメーション部門 5作品ノミネート",
