  "全台指標性數位內容競賽": "台湾を代表する指標的デジタルコンテンツコンテスト",
  "全台指標性數位內容競賽「2025 放視大賞」共 8 件畢業製作入圍。 動畫類 5 部：《失竊的祕方》、《人造人》、《癡迷的現實》、《妖夢》、《神癒》 遊戲類 3 部：《糖霧之謎》、《眼及之處》、《Trace》": "台湾を代表するデジタルコンテンツコンテスト「2025 放視大賞」において、卒業制作計8作品がノミネートされました。アニメーション部門 5作品：《失竊的祕方》、《人造人》、《癡迷的現實》、《妖夢》、《神癒》 ゲーム部門 3作品：《糖霧之謎》、《眼及之處》、《Trace》",
  "蘇中和教授 · 全球前 2% 頂尖科學家": "蘇中和教授 · 世界の上位2%トップ科学者",
  "連四年榮登": "4年連続選出",
  "學術榮譽": "学術的栄誉",
  "蘇中和教授（動遊系）": "蘇中和教授（アニメとゲームデザイン学科）",
  "連續四年入選《全球前 2% 頂尖科學家》（World's Top 2% Scientists）": "4年連続で《全球前 2% 頂尖科學家》（World's Top 2% Scientists）に選出",
  "代表性論文單篇引用次數已超過數千次": "代表的な単一論文の被引用回数は数千回を突破",
  "在教育研究領域名列全球前 2% 頂尖水準": "教育研究分野において世界トップ2%の水準にランクイン",
  "蘇中和教授（副校長暨設計學院院長）連續四年入選《全球前 2% 頂尖科學家》（World's Top 2% Scientists），代表性論文單篇引用次數已超過數千次，在教育研究領域名列全球前 2% 頂尖水準。 研究範疇涵蓋設計教育、遊戲化 STEM 教育、數位雙生與擴增實境設計，並成功跨足智慧設計與 AI 影像處理。": "蘇中和教授（副学長兼設計学院長）は4年連続で《全球前 2% 頂尖科學家》（World's Top 2% Scientists）に選出されました。代表的な論文1本の被引用数は数千回を超え、教育研究分野において世界トップ2%の水準に位置づけられています。研究領域はデザイン教育、ゲーミフィケーションSTEM教育、デジタルツイン、拡張現実（AR）デザインに及び、スマートデザインやAI画像処理の分野にも幅広く展開しています。",
