  "設計力出海！動遊系赴日實習邁入第九屆": "デザイン力で世界へ！アニメとゲームデザイン学科の日本でのインターンシップが第9期を迎える",
  "動遊系畢製《Dear, All Robots》躍上國際媒體": "アニメとゲームデザイン学科の卒業制作『Dear, All Robots』が国際メディアに掲載",
  "全國技專專題、青春設計節、放視大賞、金點新秀 — 4 大競賽 14 件入圍，7 部畢業專題作品全榜公開。": "全國技專專題（技術系大学・短大の実践プロジェクト競技会）、青春設計節、放視大賞、金点新秀 — 4大コンテストで14件入選、卒業制作7作品の全実績を公開。",
  "《失竊的祕方》《癡迷的現實》《人造人》《神癒》登上多國影展競賽單元 — 義大利怪誕影展叛逆視野獎、西班牙愛情影展最佳奇幻類等獎項相繼到手。": "『失竊的祕方』『癡迷的現實』『人造人』『神癒』が各国の映画祭コンペティション部門に進出。イタリアの「怪誕影展」での「叛逆視野獎」、スペインの「愛情影展」での最優秀ファンタジー部門賞などを相次いで受賞しました。",
