  "畢業專題：專題設計 I、II 均為必修，依「樹德科技大學動畫與遊戲設計系畢業專題研究展演實施辦法」辦理。": "卒業制作：専題設計（プロジェクトデザイン）I・IIはともに必修であり、「樹徳科技大学アニメとゲームデザイン学科卒業制作研究展示実施規程」に基づき実施されます。",
