  "四條選修軸線為學習方向建議，非強制分流；學生可依職涯目標自由跨軸選修，建議至少深耕一條主軸以建立個人專業識別。": "4つの選択履修系統は学習方針の提案であり、強制的なコース分けではありません。学生は自身の進路目標に合わせて自由に系統を横断して履修できますが、個人の専門性を確立するため、少なくとも1つの主軸を深く学ぶことを推奨します。",
