  "我適合哪個入學管道？": "私に合った入試制度はどれ？",
  "3 題 · 第": "全3問 · 第",
  "科技繁星限應屆高職／綜合高中，而且已報名大學繁星推薦就不能重複報名科技繁星；普通型高中建議走申請入學。": "科技繁星は職業高校／総合高校の卒業見込生が対象です。また、すでに一般大学の繁星推薦に出願している場合は科技繁星への重複出願はできません。普通科高校生は申請入試の利用をおすすめします。",
  "技優甄審不限競賽獲獎的高職應屆生；115學年度也採認符合簡章職種的勞動部乙級（含）以上技術士證等資格。高中、非應屆等身分須依當年簡章核對，不可只憑身分判定可否報名。": "技優甄審は競技大会入賞者の職業高校卒業見込者だけの制度ではありません。115学年度は、要項の対象職種に適合する台湾の労働部発行の乙級以上技能士資格なども対象です。普通科高校や既卒者も、出身区分だけで判断せず当該年度の要件を確認してください。",
  "申請入學的適用對象是高中應屆畢業生（持學測成績）；高職／綜合高中的主力是統測相關管道。": "申請入試の対象は普通科高校の卒業見込生（学測成績を保有）です。職業高校／総合高校の生徒は、主に統測関連の出願区分を利用します。",
  "115 學年度科技繁星錄取生，不論是否放棄，均不得參加當年度四技二專甄選入學；其他管道請依各招生簡章與報到／放棄規定辦理。": "115学年度の科技繁星合格者は、入学資格を辞退したかどうかにかかわらず、当該年度の四技二専甄選入学（選抜入試）には出願できません。その他の入試区分は、それぞれの募集要項、入学手続き・辞退の規定に従ってください。",
  "你的推薦管道": "あなたにおすすめの入試制度",
